// EDIT BEFORE RUNNING. Default only plans ideas; no media generation or publishing.
const action = 'plan_campaign'; // plan_campaign | start_batch | resume_batch | release_batch | status
const name = 'GymFeed 28-day campaign';
const timezone = 'America/New_York';
const startDate = $now.setZone(timezone).plus({ days: 7 }).toFormat('yyyy-MM-dd'); // Replace with a fixed YYYY-MM-DD before first run.
const days = 28;
const campaignId = ''; // Copy from planning result.
const batchId = ''; // Copy from batch result for resume/release.
const batchNumber = 1; // Advance only after previous seven-day batch approval.
const requestKey = ''; // Optional override. Keep unchanged when retrying the same operation.

if (action === 'plan_campaign') {
  return [{ json: { action, name, startDate, days, timezone, requestKey: requestKey || `campaign:${name}:${startDate}:${days}:${timezone}` } }];
}
if (!campaignId) throw new Error('Set campaignId from the existing campaign result; do not create a new campaign to resume one.');
if (action === 'start_batch') {
  return [{ json: { action, campaignId, batchNumber, requestKey: requestKey || `campaign:${campaignId}:batch:${batchNumber}` } }];
}
if (action === 'resume_batch' || action === 'release_batch') {
  if (!batchId) throw new Error('Set batchId from the batch result.');
  return [{ json: { action, campaignId, batchId } }];
}
if (action === 'status') return [{ json: { action, campaignId } }];
throw new Error(`Unsupported manual action: ${action}`);
